const execData = $json.execution;
const workflowName = $json.workflow.name;
const errorObj = execData.error || {};
const errorMessage = errorObj.message || 'Unknown error occurred';
const errorNode = errorObj.lastNodeExecuted || 'Unknown node';

return [{
  json: {
    message: `🚨 *N8N WORKFLOW ERROR* 🚨\n\n*Workflow:* ${workflowName}\n*Failed Node:* ${errorNode}\n*Error:* ${errorMessage}\n\nPlease check your n8n dashboard to fix the issue.`
  }
}];
